    nullable: ['cco', 'cno2', 'cso2', 'cnh3'], zero: ['cco', 'cno2', 'cso2', 'cnh3', 'bg'], neg: ['Tv'],
    fields: [
      ['cco', 'C<sup>CO</sup>', 'Концентрация CO в выбросах', 'мг/м³'], ['cno2', 'C<sup>NO₂</sup>', 'Концентрация NO₂', 'мг/м³'],
      ['cso2', 'C<sup>SO₂</sup>', 'Концентрация SO₂', 'мг/м³'], ['cnh3', 'C<sup>NH₃</sup>', 'Концентрация NH₃', 'мг/м³'],
      ['H', 'H', 'Высота трубы', 'м'], ['Lw', 'L', 'Длина устья', 'м'], ['Bw', 'B', 'Ширина устья', 'м'], ['W', 'W', 'Скорость выхода газов', 'м/с'],
      ['Tg', 'T<sub>г</sub>', 'Температура газов', '°C'], ['Tv', 'T<sub>в</sub>', 'Температура воздуха', '°C'], ['A', 'A', 'Коэффициент стратификации', ''], ['bg', 'C<sub>ф</sub>/ПДК', 'Фон в долях ПДК', '']
    ],
    adv: [['pdk_co', 'ПДК<sup>CO</sup>', 'ПДК м.р. CO', 'мг/м³'], ['pdk_no2', 'ПДК<sup>NO₂</sup>', 'ПДК м.р. NO₂', 'мг/м³'], ['pdk_so2', 'ПДК<sup>SO₂</sup>', 'ПДК м.р. SO₂', 'мг/м³'], ['pdk_nh3', 'ПДК<sup>NH₃</sup>', 'ПДК м.р. NH₃', 'мг/м³']],
    advTitle: 'ПДК вредных веществ',
