  const COMP5 = [
    { key: 'co', name: 'Оксид углерода', html: 'CO', tex: '\\mathrm{CO}', short: 'CO' },
    { key: 'no', name: 'Оксиды азота', html: 'NO', tex: '\\mathrm{NO}', short: 'NO' },
    { key: 'ch', name: 'Углеводороды', html: 'CH', tex: '\\mathrm{CH}', short: 'CH' }
  ];
  /* мощность эмиссии по рис. 1.1, ×10⁻³ мг/(м·с) */
  function qOf(key, V) {
    const g = D.qGraph, a = g[key], t = (V - g.V0) / g.dV;
    if (t <= 0) return a[0];
    if (t >= a.length - 1) return a[a.length - 1];
    const i = Math.floor(t);
    return a[i] + (a[i + 1] - a[i]) * (t - i);
  }
  function kHof(h) {
    if (h < 0) return { k: 0.66, row: 0, why: `проезжая часть расположена в выемке глубиной ${fin(Math.abs(h))} м (выемки до 12 м)` };
    if (h <= 1) return { k: 0.63, row: 1, why: `проезжая часть расположена на насыпи высотой ${fin(h)} м (насыпь до 1 м)` };
    if (h < 5) return { k: 0.60, row: 2, why: `возвышение проезжей части ${fin(h)} м (возвышение до 5 м)` };
    return { k: 0.50, row: 3, why: `проезжая часть на эстакаде высотой ${fin(h)} м (эстакада ≥ 5 м)` };
  }
  function sigmaOf(W, Lr) {
    const s = D.sigma, row = W <= 2 ? s.w2 : s.w5, Ls = s.L;
    let v, exact = true;
    if (Lr <= Ls[0]) { v = row[0]; exact = Lr === Ls[0]; }
    else if (Lr >= Ls[Ls.length - 1]) { v = row[row.length - 1]; exact = Lr === Ls[Ls.length - 1]; }
    else { const i = Ls.findIndex((x, k) => Lr >= x && Lr <= Ls[k + 1]); const t = (Lr - Ls[i]) / (Ls[i + 1] - Ls[i]); v = row[i] + (row[i + 1] - row[i]) * t; exact = t === 0 || t === 1; }
    return { v: rd(v, 2), exact, w2: W <= 2 };
  }
  const qDec = q => (+(q / 1000).toPrecision(book() ? 2 : 4));
  const qT = q => tx(String(qDec(q)).replace('.', ','));
  function compute5(P) {
    ['Ncar', 'Lr', 'V', 'A0', 'KM', 'VT'].forEach(k => { if (!(+P[k] > 0)) throw new Error('параметр ' + k + ' должен быть положительным'); });
    if (!(+P.Wr >= 0)) throw new Error('скорость ветра не может быть отрицательной');
    const R = { P };
    const kh = kHof(+P.Hr), sg = sigmaOf(+P.Wr, +P.Lr);
    R.kh = kh; R.sg = sg;
    const sq = book() ? Math.sqrt(3.14) : Math.sqrt(Math.PI);
    R.sub = COMP5.map(c => {
      const auto = rs(qOf(c.key, +P.V), 2), user = P['q' + c.key];
      const Q = user !== null && user !== undefined && user !== '' ? +user : auto;
      const C = rd(P.Ncar * Q / 1000 * P.A0 * kh.k * P.KM / (sq * sg.v * P.VT), 2);
      const PDK = +P['pdk5_' + c.key];
      return { s: c, key: c.key, Q, auto, user: Q !== auto, C, PDK, ratio: C / PDK, exceed: C > PDK };
    });
    R.by = {}; R.sub.forEach(x => R.by[x.key] = x);
    R.q = rd(R.sub.reduce((a, x) => a + x.C / x.PDK, 0), 2);
    R.qok = R.q <= 1;
    R.excList = R.sub.filter(x => x.exceed);
    const L1 = new Report(), L2 = new Report(), L3 = new Report();
    if (book()) L1.note('Режим «как в методичке»: мощность эмиссии Q<sub>i</sub> по рис. 1.1 берётся с двумя значащими цифрами, π = 3,14, концентрации C<sub>i</sub> и суммарный показатель — до 0,01, как в примере решения.').webOnly();
    /* этап 1 */
    L1.h('1.1. Мощность эмиссии токсичных компонентов');
    L1.p(`Мощность эмиссии Q<sub>i</sub> оксида углерода, оксидов азота и углеводородов при средней скорости движения автомобилей V = ${fin(P.V)} км/ч определяем по графикам рис. 1.1 [1]:`);
    L1.table(['Компонент', 'Q<sub>i</sub>, мг/(м·с)'], R.sub.map(x => [x.s.name + ' (' + x.s.html + ')', String(qDec(x.Q)).replace('.', ',')]), 'Мощность эмиссии газов при V = ' + fin(P.V) + ' км/ч', { cols: [5354, 4000] });
    L1.note('Значения Q<sub>i</sub> сняты с оцифрованных кривых рис. 1.1 пособия (точность чтения графика — около 2 %). ' + (R.sub.some(x => x.user) ? 'Часть значений задана вручную на вкладке «Исходные данные».' : 'Если в вашем решении значения прочитаны иначе, задайте их вручную на вкладке «Исходные данные».') + (+P.variant === 1 && !R.sub.some(x => x.user) ? ' В примере пособия для варианта 1 приняты Q = 0,0021; 0,0003 и 0,00068 мг/(м·с); по графику NO ≈ 0,00031 — на результат C<sup>NO</sup> = 0,02 мг/м³ это не влияет.' : ''), 'info').webOnly();
    if (+P.V < 10 || +P.V > 80) L1.note('Скорость V выходит за пределы графика рис. 1.1 (10–80 км/ч): принято значение на границе графика.', 'warn').webOnly();
    L1.ext(true).plot('qv', 'Мощность эмиссии газов в зависимости от скорости движения (по рис. 1.1 пособия)');
    L1.items[L1.items.length - 1].lead = 'Зависимость мощности эмиссии от скорости движения представлена на рисунке {n}.';
    L1.ext(false);
    L1.h('1.2. Коэффициент K<sub>Н</sub>');
    L1.p(`Поскольку ${kh.why}, по табл. 1.6 [1] коэффициент, учитывающий возвышение проезжей части над окружающей местностью, K<sub>Н</sub> = ${fin(kh.k)}.`);
    if (+P.Hr < -12) L1.note('Глубина выемки больше 12 м — табл. 1.6 такой случай не охватывает; принято K<sub>Н</sub> = 0,66.', 'warn').webOnly();
    L1.h('1.3. Коэффициент вертикального рассеивания');
    L1.p(`При скорости ветра W = ${fin(P.Wr)} м/с (${sg.w2 ? 'до 2 м/с' : '2–5 м/с'}) и длине участка дороги L = ${fin(P.Lr)} м по табл. 1.7 [1] коэффициент вертикального рассеивания Гаусса σ = ${fk(sg.v, 2)}${sg.exact ? '' : ' (линейная интерполяция по L)'}.`);
    L1.h('1.4. Прочие коэффициенты');
    L1.p(`Коэффициент стратификации атмосферы для Казани A<sub>0</sub> = ${fin(P.A0)}; коэффициент, учитывающий наличие защитных насаждений, K<sub>М</sub> = ${fin(P.KM)}; при скорости ветра до 5 м/с и скорости движения до 80 км/ч показатель турбулентности V<sub>Т</sub> = ${fin(P.VT)} м/с [1].`);
    if (+P.Wr >= 5 || +P.V >= 80) L1.note('Значение V<sub>Т</sub> = 0,25 м/с в пособии дано только для W < 5 м/с и V < 80 км/ч; при других условиях задайте V<sub>Т</sub> вручную.', 'warn').webOnly();
    /* этап 2 */
    L2.h('2.1. Концентрации токсичных компонентов');
    L2.p('Концентрацию C<sub>i</sub> (мг/м³) токсичных компонентов в отработавших газах в зоне действия автомобильной дороги определяем по формуле (1.38):');
    L2.tex('C_i=\\dfrac{NQ_iA_0K_{Н}K_{М}}{\\sqrt{\\pi}\\,\\sigma V_{Т}}', 'ci');
    for (const x of R.sub) L2.eq('C^{' + x.s.tex + '}', '', `\\dfrac{${n0(P.Ncar)}\\cdot ${qT(x.Q)}\\cdot ${n0(P.A0)}\\cdot ${n0(kh.k)}\\cdot ${n0(P.KM)}}{\\sqrt{${book() ? '3{,}14' : '\\pi'}}\\cdot ${nk(sg.v, 2)}\\cdot ${n0(P.VT)}}`, x.C, 'мг/м³', nk(x.C, 2), 'C_i');
    /* этап 3 */
    L3.h('3.1. Сравнение с предельно допустимыми концентрациями');
    L3.p('Сравниваем концентрации C<sub>i</sub> токсичных веществ с их среднесуточными предельно допустимыми концентрациями:');
    L3.table(['Компонент', 'C<sub>i</sub>, мг/м³', 'ПДК<sub>с.с.</sub>, мг/м³', 'C<sub>i</sub> / ПДК', 'Превышение ПДК'],
      R.sub.map(x => [x.s.name + ' (' + x.s.html + ')', fk(x.C, 2), fin(x.PDK), fa(x.ratio, 3), x.exceed ? 'да, в ' + fa(x.ratio, 3) + ' раза' : 'нет']), 'Сравнение концентраций с ПДК', { cols: [2754, 1500, 1800, 1500, 1800] });
    for (const x of R.sub) L3.check(`C^{${x.s.tex}}=${nk(x.C, 2)}\\ ${x.exceed ? '>' : '\\le'}\\ ПДК^{${x.s.tex}}_{с.с.}=${n0(x.PDK)}`, !x.exceed, x.exceed ? 'концентрация превышает ПДК' : 'концентрация не превышает ПДК').webOnly();
    L3.p(R.excList.length ? `Фактическая концентрация ${R.excList.map(x => x.s.html).join(', ')} превышает ПДК; концентрации остальных компонентов ниже ПДК.` : 'Для данного варианта фактические концентрации токсичных веществ не превышают значений их ПДК.');
    L3.h('3.2. Степень загазованности');
    L3.p('Степень загазованности в зоне расположения автомобильной дороги определяем на основе неравенства (1.1), так как компоненты отработавших газов действуют совместно:');
    L3.eq('q', '\\dfrac{C^{\\mathrm{CO}}}{ПДК^{\\mathrm{CO}}}+\\dfrac{C^{\\mathrm{NO}}}{ПДК^{\\mathrm{NO}}}+\\dfrac{C^{\\mathrm{CH}}}{ПДК^{\\mathrm{CH}}}', R.sub.map(x => `\\dfrac{${nk(x.C, 2)}}{${n0(x.PDK)}}`).join('+'), R.q, '', nk(R.q, 2), 'q5');
    L3.check(`q=${nk(R.q, 2)}\\ ${R.qok ? '\\le' : '>'}\\ 1`, R.qok, R.qok ? 'Условие (1.1) выполняется.' : 'Условие (1.1) не выполняется.');
    if (book() && +P.variant === 1 && !R.sub.some(x => x.user)) L3.note('В примере пособия сумма 0,15/3 + 0,02/0,06 + 0,05/1,5 записана как 0,41; арифметически она равна 0,4167 ≈ 0,42. Вывод не меняется.', 'warn').webOnly();
    L3.h('3.3. Вывод об уровне загазованности');
    L3.p(R.qok && !R.excList.length ? 'Таким образом, уровень загазованности атмосферного воздуха в районе расположения дороги не превышает санитарных норм.'
      : 'Таким образом, уровень загазованности атмосферного воздуха в районе расположения дороги превышает санитарные нормы. Для его снижения необходимы мероприятия: ограничение интенсивности движения и перераспределение транспортных потоков, обеспечение равномерного движения с оптимальной скоростью, устройство защитных зелёных насаждений вдоль дороги (уменьшение K<sub>М</sub>), контроль токсичности отработавших газов автомобилей.');
    Object.assign(R, { L1, L2, L3 });
    return R;
  }
  function drawQ(el, ex, R, CH) {
    const th = CH.theme(ex && ex.export), Vs = [];
    for (let v = 10; v <= 80; v += 1) Vs.push(v);
    const dash = th.mono ? ['solid', 'dash', 'dot'] : ['solid', 'solid', 'solid'];
    const data = COMP5.map((c, k) => ({ x: Vs, y: Vs.map(v => qOf(c.key, v)), name: c.html + ' (×10⁻³ мг/(м·с))', type: 'scatter', mode: 'lines', line: { color: th.c[k], width: 1.8, dash: dash[k] }, hovertemplate: c.html + ': %{y:.3f}<extra></extra>' }));
    const V = +R.P.V;
    data.push({ x: R.sub.map(() => V), y: R.sub.map(x => x.Q), name: 'V = ' + fin(V) + ' км/ч', type: 'scatter', mode: 'markers', marker: { color: th.fg, size: 7, symbol: 'circle-open', line: { width: 1.6 } }, hovertemplate: '%{y:.3f}<extra></extra>' });
    const lay = { height: (ex && ex.h) || 340, separators: ', ', margin: { l: 58, r: 14, t: 34, b: 46 }, paper_bgcolor: th.paper, plot_bgcolor: th.bg, font: { family: (getComputedStyle(document.documentElement).getPropertyValue('--f-body').trim() || '"IBM Plex Sans", "Segoe UI", Arial, sans-serif'), size: 12, color: th.fg },
      showlegend: true, hovermode: 'x unified', legend: { orientation: 'h', x: 0, y: 1.02, yanchor: 'bottom', bgcolor: 'rgba(0,0,0,0)', font: { size: 11 } } };
    const ax = t => ({ title: { text: t, font: { size: 12, color: th.fg } }, showline: true, mirror: true, linecolor: th.axis, ticks: 'inside', tickcolor: th.axis, gridcolor: th.grid, griddash: 'dot', zeroline: false, automargin: true });
    lay.xaxis = Object.assign(ax('V — скорость движения, км/ч'), { range: [10, 80] }); lay.yaxis = Object.assign(ax('Q, ×10⁻³ мг/(м·с)'), { rangemode: 'tozero' });
    lay.shapes = [{ type: 'line', xref: 'x', x0: V, x1: V, yref: 'paper', y0: 0, y1: 1, line: { color: th.muted, width: 1, dash: 'dot' } }];
    const w = el.querySelector && el.querySelector('.plot-wait'); if (w) w.remove();
    return Plotly.react(el, data, lay, CH.config);
  }
