    L1.eq('У_{к}', '', `${nC(u.kd.v)}+${nC(u.ks.v)}`, Uk, '', n0(Uk), 'Uk');
    /* этап 2 */
    L2.h('2.1. Общий экономический ущерб');
    L2.p('Общий экономический ущерб от загрязнения воздуха определяем по формуле (1.39):');
