    const nz = R.terms.filter(t => t.v !== 0);
    L2.eq('У', '', nz.length ? nz.map(t => `${n0(t.a)}\\cdot ${moneyT(t.b)}`).join('+') : '0', R.U, 'руб./год', moneyT(R.U), 'U6');
    if (+P.variant === 1 && Math.abs(R.U - 1008100) < 0.01) L2.note('В примере пособия получено У = 35·7000 + 37·7000 + 35·7000 + 37·7000 = 1 008 000 руб./год: слагаемое У<sub>п</sub>Ф = 0,2·500 = 100 руб./год (ущерб промышленности от SO<sub>2</sub>, табл. 1.9) в примере пропущено. С ним У = 1 008 100 руб./год, и экономический эффект получается ровно 300 000 руб./год.', 'warn').webOnly();
    L2.ext(true);
    L2.h('2.2. Структура ущерба');
    L2.p('Вклад составляющих в общий экономический ущерб (сверх задания):');
    L2.table(['Составляющая', 'Ущерб, руб./год', 'Доля, %'], [['Здравоохранению (У<sub>з</sub>R)', money(R.terms[0].v), fa(R.U ? R.terms[0].v / R.U * 100 : 0, 3)], ['Сельскому и лесному хозяйству (У<sub>с</sub>S)', money(R.terms[1].v), fa(R.U ? R.terms[1].v / R.U * 100 : 0, 3)],
      ['Промышленности (У<sub>п</sub>Ф)', money(R.terms[2].v), fa(R.U ? R.terms[2].v / R.U * 100 : 0, 3)], ['Коммунальному хозяйству (У<sub>к</sub>R)', money(R.terms[3].v), fa(R.U ? R.terms[3].v / R.U * 100 : 0, 3)]], 'Структура экономического ущерба', { cols: [4954, 2400, 2000] });
    L2.ext(false);
    /* этап 3 */
    L3.h('3.1. Экономический эффект от очистки');
    L3.p(`При осуществлении очистки промышленных выбросов её стоимость составляет З = ${money(R.Z)} руб./год (в ценах 2002 г.) [1]. Экономический эффект от очистки равен предотвращённому ущербу за вычетом затрат на очистку:`);
    L3.eq('Э', 'У-З', `${moneyT(R.U)}-${moneyT(R.Z)}`, R.E, 'руб./год', moneyT(R.E), 'E6');
